import React, { useState } from 'react';
import './LoginForm.css';
import { FaUser, FaLock } from "react-icons/fa";
import { useNavigate } from 'react-router-dom';

export const LoginForm = () => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const navigate = useNavigate();

  const handleSubmit = (e) => {
    e.preventDefault();

    if (username === 'admin' && password === 'admin123') {
      navigate('/admin');
    } else if (username === 'student' && password === 'student123') {
      const user = {
        name: "Carlos",
        id: 123,
        courses: [
          { id: 1, name: "Matemáticas" },
          { id: 2, name: "Historia" },
          { id: 3, name: "Programación Web" }
        ]
      };
      navigate('/student', { state: { user } });
    } else if (username === 'professor' && password === 'professor123') {
      const user = {
        name: "Dra. López",
        id: 456,
        courses: [
          { id: 10, name: "Algoritmos" },
          { id: 20, name: "Bases de Datos" },
          { id: 30, name: "Inteligencia Artificial" }
        ]
      };
      navigate('/professor', { state: { user } });
    } else {
      setError('Usuario o contraseña inválido');
    }
  };


  return (
    <div className='wrapper'>
      <form onSubmit={handleSubmit}>
        <h1>Login</h1>

        <div className="input-box">
          <input
            type="text"
            placeholder="Username"
            required
            value={username}
            onChange={(e) => setUsername(e.target.value)}
          />
          <FaUser className='icon' />
        </div>

        <div className="input-box">
          <input
            type="password"
            placeholder="Password"
            required
            value={password}
            onChange={(e) => setPassword(e.target.value)}
          />
          <FaLock className='icon' />
        </div>

        {error && <p className="error-message">{error}</p>}

        <div className="remember-forgot">
          <label><input type='checkbox' /> Remember me</label>
          <a href="#">Forgot Password?</a>
        </div>

        <button type="submit">Login</button>

        <div className="register-link">
          <p>Don’t have an account? <a href="#">Register</a></p>
        </div>
      </form>
    </div>
  );
};
